import { useState, useEffect, useRef } from 'react';

const API = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');
const gc = g => g==='A+'||g==='A'?'#16a34a':g==='F'?'#dc2626':g==='B'?'#2563eb':'#d97706';

// Configurable year options — admin can set, student can progress through
const YEAR_OPTIONS = ['1st Year','2nd Year','3rd Year','4th Year','5th Year','Postgraduate'];
const DEPT_OPTIONS = [
  'Computer Science','Computer Engineering','Information Technology',
  'Electronics & Communication','Electrical Engineering','Mechanical Engineering',
  'Civil Engineering','Chemical Engineering','Biotechnology','Mathematics',
  'Physics','Chemistry','Commerce','Business Administration','Other',
];

export default function StudentProfile({ store }) {
  const [profile,  setProfile]  = useState(null);
  const [progress, setProgress] = useState([]);
  const [editing,  setEditing]  = useState(false);
  const [saving,   setSaving]   = useState(false);
  const [msg,      setMsg]      = useState('');
  const [form,     setForm]     = useState({});
  const fileRef = useRef();

  const apiFetch = async (p, opts={}) => {
    const r = await fetch(`${API}${p}`, { headers:{ Authorization:`Bearer ${getToken()}`, 'Content-Type':'application/json' }, ...opts });
    return r.json();
  };

  useEffect(() => { load(); }, []);

  const load = async () => {
    const [p, prog] = await Promise.all([
      apiFetch('/profile'),
      apiFetch(`/profile/progress/${store.currentStudent?.student_id||store.currentUser?.user_id}`),
    ]);
    setProfile(p);
    setProgress(Array.isArray(prog) ? prog : []);
    setForm({
      name:       p.name || '',
      department: p.student?.department || '',
      year:       p.student?.year || '1st Year',
      bio:        p.bio || '',
    });
  };

  const handleSave = async () => {
    if (!form.name.trim()) { setMsg('Name is required'); return; }
    setSaving(true); setMsg('');
    const updated = await apiFetch('/profile', { method:'PUT', body:JSON.stringify(form) });
    if (updated.error) { setMsg('❌ ' + updated.error); }
    else { setProfile(updated); setEditing(false); store.addToast('Profile updated!','success'); }
    setSaving(false);
  };

  const handleAvatar = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 2*1024*1024) { store.addToast('Image must be < 2MB','error'); return; }
    const reader = new FileReader();
    reader.onload = async (ev) => {
      const updated = await apiFetch('/profile', { method:'PUT', body:JSON.stringify({ avatar_url: ev.target.result }) });
      if (!updated.error) { setProfile(updated); store.addToast('Photo updated!','success'); }
    };
    reader.readAsDataURL(file);
  };

  const cancelEdit = () => {
    setEditing(false); setMsg('');
    setForm({ name:profile.name||'', department:profile.student?.department||'', year:profile.student?.year||'1st Year', bio:'' });
  };

  const avgPct  = progress.length ? Math.round(progress.reduce((a,p)=>a+(Number(p.total_score)/Number(p.total_marks)*100),0)/progress.length) : 0;
  const bestG   = progress.length ? progress.reduce((b,p)=>['A+','A','B','C','D','F'].indexOf(p.grade)<['A+','A','B','C','D','F'].indexOf(b)?p.grade:b,'F') : '—';

  if (!profile) return (
    <div style={{ display:'flex', alignItems:'center', gap:12, padding:60, justifyContent:'center' }}>
      <div className="spinner" style={{width:24,height:24}}/><span style={{color:'#6b7280'}}>Loading profile...</span>
    </div>
  );

  const FLabel = ({ children }) => (
    <label style={{ display:'block', fontSize:10, fontWeight:700, color:'#7c3aed', marginBottom:5, textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace' }}>{children}</label>
  );

  return (
    <div className="fade-up" style={{ display:'grid', gridTemplateColumns:'260px 1fr', gap:20, alignItems:'start' }}>

      {/* ── LEFT SIDEBAR ── */}
      <div style={{ display:'flex', flexDirection:'column', gap:14 }}>

        {/* Profile card */}
        <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:16, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
          {/* Banner */}
          <div style={{ height:72, background:'linear-gradient(135deg,#ede9fe,#ddd6fe,#c4b5fd)', position:'relative' }}>
            <div style={{ position:'absolute', bottom:-24, left:20 }}>
              <div style={{ position:'relative', display:'inline-block' }}>
                <div style={{ width:60, height:60, borderRadius:'50%', overflow:'hidden', border:'3px solid #fff', background:'linear-gradient(135deg,#7c3aed,#6d28d9)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:24, fontWeight:900, color:'white', boxShadow:'0 2px 10px rgba(124,58,237,.3)', cursor:'pointer' }}
                  onClick={() => !editing && fileRef.current?.click()}>
                  {profile.avatar_url ? <img src={profile.avatar_url} alt="" style={{width:'100%',height:'100%',objectFit:'cover'}}/> : profile.name?.charAt(0).toUpperCase()}
                </div>
                {!editing && (
                  <button onClick={() => fileRef.current?.click()}
                    style={{ position:'absolute', bottom:-1, right:-1, width:20, height:20, borderRadius:'50%', background:'#7c3aed', border:'2px solid #fff', cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center', fontSize:9, color:'#fff' }}>✏</button>
                )}
                <input ref={fileRef} type="file" accept="image/*" style={{display:'none'}} onChange={handleAvatar}/>
              </div>
            </div>
          </div>

          <div style={{ padding:'32px 18px 18px' }}>
            {editing ? (
              /* ── EDIT MODE ── */
              <div>
                <div style={{ marginBottom:12 }}>
                  <FLabel>Full Name</FLabel>
                  <input className="form-input" value={form.name}
                    onChange={e=>setForm(f=>({...f,name:e.target.value}))}
                    placeholder="Your full name" style={{ fontSize:13 }}/>
                </div>

                <div style={{ marginBottom:12 }}>
                  <FLabel>Department</FLabel>
                  <select className="form-select" value={form.department}
                    onChange={e=>setForm(f=>({...f,department:e.target.value}))}
                    style={{ fontSize:13 }}>
                    <option value="">Select department...</option>
                    {DEPT_OPTIONS.map(d => <option key={d} value={d}>{d}</option>)}
                  </select>
                  {/* Custom department input if 'Other' or not in list */}
                  {(form.department === 'Other' || (form.department && !DEPT_OPTIONS.includes(form.department))) && (
                    <input className="form-input" style={{ marginTop:6, fontSize:13 }}
                      value={form.department === 'Other' ? '' : form.department}
                      onChange={e=>setForm(f=>({...f,department:e.target.value}))}
                      placeholder="Enter your department..."/>
                  )}
                </div>

                <div style={{ marginBottom:14 }}>
                  <FLabel>Academic Year</FLabel>
                  {/* Visual year selector — clickable cards */}
                  <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:6 }}>
                    {YEAR_OPTIONS.map(y => (
                      <button key={y} type="button" onClick={() => setForm(f=>({...f,year:y}))}
                        style={{ padding:'8px 6px', borderRadius:8, border:`1.5px solid ${form.year===y?'#7c3aed':'#e5e7eb'}`, background:form.year===y?'#ede9fe':'#fff', color:form.year===y?'#7c3aed':'#374151', fontSize:12, fontWeight:form.year===y?700:500, cursor:'pointer', transition:'all .15s', textAlign:'center' }}>
                        {y}
                      </button>
                    ))}
                  </div>
                  <div style={{ marginTop:6, fontSize:10, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>
                    Currently: <strong style={{color:'#7c3aed'}}>{form.year}</strong>
                  </div>
                </div>

                {msg && <div style={{ marginBottom:10, padding:'7px 10px', background:'#fee2e2', border:'1px solid #fecaca', borderRadius:7, fontSize:12, color:'#dc2626' }}>{msg}</div>}

                <div style={{ display:'flex', gap:8 }}>
                  <button className="btn btn-primary btn-sm" style={{ flex:1 }} onClick={handleSave} disabled={saving}>
                    {saving ? <><div className="spinner" style={{width:11,height:11,borderColor:'rgba(255,255,255,.3)',borderTopColor:'#fff'}}/> Saving...</> : '✓ Save Changes'}
                  </button>
                  <button className="btn btn-secondary btn-sm" onClick={cancelEdit}>Cancel</button>
                </div>
              </div>
            ) : (
              /* ── VIEW MODE ── */
              <>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:17, color:'#0f0f1a', marginBottom:3 }}>{profile.name}</div>
                <div style={{ fontSize:12, color:'#9ca3af', marginBottom:12, fontFamily:'JetBrains Mono,monospace' }}>{profile.email}</div>

                {/* Tags */}
                <div style={{ display:'flex', gap:6, flexWrap:'wrap', marginBottom:14 }}>
                  {[
                    { v:profile.student?.department||'N/A',  bg:'#ede9fe', c:'#7c3aed' },
                    { v:profile.student?.year||'',            bg:'#dbeafe', c:'#2563eb' },
                    { v:'Student',                            bg:'#dcfce7', c:'#16a34a' },
                  ].filter(t=>t.v).map((t,i) => (
                    <span key={i} style={{ padding:'3px 10px', background:t.bg, color:t.c, borderRadius:6, fontSize:11, fontWeight:700 }}>{t.v}</span>
                  ))}
                </div>

                <button className="btn btn-primary btn-sm" style={{ width:'100%', fontSize:12 }} onClick={() => setEditing(true)}>
                  ✏ Edit Profile
                </button>
              </>
            )}
          </div>
        </div>

        {/* Stats */}
        <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:16, boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a', marginBottom:12 }}>My Stats</div>
          {[
            { icon:'📄', label:'EXAMS TAKEN',  value:progress.length },
            { icon:'📊', label:'AVG SCORE',    value:`${avgPct}%` },
            { icon:'🏆', label:'BEST GRADE',   value:bestG, color:gc(bestG) },
            { icon:'📅', label:'MEMBER SINCE', value:new Date(profile.created_at).toLocaleDateString('en-US',{month:'short',year:'numeric'}) },
          ].map((s,i) => (
            <div key={i} style={{ display:'flex', alignItems:'center', gap:10, padding:'9px 0', borderBottom:i<3?'1px solid #f3f4f6':'none' }}>
              <div style={{ width:28, height:28, borderRadius:7, background:'#f3f4f6', display:'flex', alignItems:'center', justifyContent:'center', fontSize:14, flexShrink:0 }}>{s.icon}</div>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:9, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace' }}>{s.label}</div>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:15, color:s.color||'#0f0f1a' }}>{s.value}</div>
              </div>
            </div>
          ))}
        </div>

        {/* Degree */}
        <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:14, boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
          <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:7 }}>
            <span style={{ fontSize:16 }}>🎓</span>
            <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:13, color:'#0f0f1a' }}>Academic Degree</span>
          </div>
          <div style={{ fontSize:12, color:'#6b7280', lineHeight:1.6 }}>
            Bachelor of Technology in {profile.student?.department||'Computer Science'} and Engineering
          </div>
          <div style={{ marginTop:8, display:'flex', alignItems:'center', gap:6 }}>
            {/* Year progression visual */}
            {YEAR_OPTIONS.slice(0,4).map((y,i) => {
              const current = profile.student?.year;
              const currentIdx = YEAR_OPTIONS.indexOf(current);
              const done  = i < currentIdx;
              const active= y === current;
              return (
                <div key={y} style={{ flex:1, textAlign:'center' }}>
                  <div style={{ height:4, borderRadius:2, background:done?'#7c3aed':active?'#7c3aed':'#e5e7eb', opacity:active?1:done?0.6:1, marginBottom:4 }}/>
                  <div style={{ fontSize:8, color:active?'#7c3aed':done?'#9ca3af':'#d1d5db', fontFamily:'JetBrains Mono,monospace', fontWeight:active?700:400 }}>{i+1}Y</div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* ── RIGHT CONTENT ── */}
      <div>
        {/* Score chart */}
        <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:'20px 24px', marginBottom:16, boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
            <div>
              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a', display:'flex', alignItems:'center', gap:6 }}>
                <span>📈</span> Score Progress
              </div>
              <div style={{ fontSize:12, color:'#9ca3af', marginTop:2 }}>Your academic growth over {progress.length} exam{progress.length!==1?'s':''}</div>
            </div>
            <div style={{ fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', background:'#f3f4f6', padding:'3px 10px', borderRadius:6 }}>2024 Session</div>
          </div>

          {progress.length === 0 ? (
            <div style={{ textAlign:'center', padding:32 }}>
              <div style={{ fontSize:32, marginBottom:10, opacity:.2 }}>📊</div>
              <div style={{ fontSize:13, color:'#9ca3af' }}>No exam history yet. Complete exams to see your progress.</div>
            </div>
          ) : (() => {
            const W=560,H=180,PL=44,PR=16,PT=20,PB=28,CW=W-PL-PR,CH=H-PT-PB;
            const xOf=(i)=>PL+(progress.length>1?i/(progress.length-1):0.5)*CW;
            const yOf=(p)=>PT+CH-(Number(p.total_score)/Number(p.total_marks))*CH;
            const pts=progress.map((p,i)=>`${xOf(i)},${yOf(p)}`).join(' ');
            const area=[`${xOf(0)},${PT+CH}`,...progress.map((p,i)=>`${xOf(i)},${yOf(p)}`),`${xOf(progress.length-1)},${PT+CH}`].join(' ');
            return (
              <div style={{ background:'#f8f8fc', borderRadius:10, padding:'12px 8px 4px', border:'1px solid #e8e8f0' }}>
                <svg width="100%" viewBox={`0 0 ${W} ${H}`} style={{display:'block',overflow:'hidden'}}>
                  <defs>
                    <linearGradient id="pg4" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#7c3aed" stopOpacity="0.2"/>
                      <stop offset="100%" stopColor="#7c3aed" stopOpacity="0.02"/>
                    </linearGradient>
                    <clipPath id="cc4"><rect x={PL} y={PT} width={CW} height={CH}/></clipPath>
                  </defs>
                  {[0,25,50,75,100].map(pct=>{
                    const y=PT+CH-(pct/100)*CH;
                    return(<g key={pct}>
                      <line x1={PL} y1={y} x2={PL+CW} y2={y} stroke="#e8e8f0" strokeWidth="1" strokeDasharray={pct>0?"4,4":""}/>
                      <text x={PL-6} y={y+4} fontSize="9" fill="#9ca3af" textAnchor="end" fontFamily="JetBrains Mono,monospace">{pct}</text>
                    </g>);
                  })}
                  {progress.length>1&&<polygon points={area} fill="url(#pg4)" clipPath="url(#cc4)"/>}
                  {progress.length>1&&<polyline points={pts} fill="none" stroke="#7c3aed" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" clipPath="url(#cc4)"/>}
                  {progress.map((p,i)=>{
                    const x=xOf(i),y=yOf(p),pct=Math.round(Number(p.total_score)/Number(p.total_marks)*100);
                    const color=gc(p.grade);
                    const ly=y-14<PT+10?y+20:y-14;
                    return(<g key={i}>
                      <circle cx={x} cy={y} r="5" fill={color} stroke="white" strokeWidth="2.5"/>
                      <text x={x} y={ly} fontSize="10" fill={color} textAnchor="middle" fontFamily="JetBrains Mono,monospace" fontWeight="700">{pct}%</text>
                    </g>);
                  })}
                  {progress.map((p,i)=>(<text key={i} x={xOf(i)} y={H-6} fontSize="9" fill="#9ca3af" textAnchor="middle" fontFamily="JetBrains Mono,monospace">{p.title?.slice(0,7)}{p.title?.length>7?'…':''}</text>))}
                </svg>
              </div>
            );
          })()}
        </div>

        {/* Results table */}
        <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
          <div style={{ padding:'14px 20px', borderBottom:'1px solid #f3f4f6', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a' }}>Recent Exam Results</div>
            <button className="btn btn-ghost btn-sm" style={{ color:'#7c3aed', fontSize:12 }}>View All →</button>
          </div>
          {progress.length===0 ? (
            <div style={{ textAlign:'center', padding:28 }}>
              <div style={{ fontSize:24, marginBottom:8, opacity:.2 }}>📋</div>
              <div style={{ fontSize:13, color:'#9ca3af' }}>No exam history yet</div>
            </div>
          ) : (
            <table style={{ width:'100%', borderCollapse:'collapse' }}>
              <thead><tr style={{ background:'#f8f8fc' }}>
                {['#','EXAM','SCORE','%','GRADE','DATE'].map(h=>(
                  <th key={h} style={{ padding:'9px 16px', textAlign:'left', fontSize:9, fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', borderBottom:'1px solid #f3f4f6' }}>{h}</th>
                ))}
              </tr></thead>
              <tbody>
                {[...progress].reverse().slice(0,6).map((p,i)=>{
                  const pct=Math.round(Number(p.total_score)/Number(p.total_marks)*100);
                  const color=gc(p.grade);
                  return (
                    <tr key={i} style={{ borderBottom:'1px solid #f3f4f6', transition:'background .15s' }}
                      onMouseEnter={e=>e.currentTarget.style.background='#f8f8fc'}
                      onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                      <td style={{ padding:'11px 16px', fontSize:12, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>{i+1}</td>
                      <td style={{ padding:'11px 16px', fontWeight:700, color:'#0f0f1a', fontSize:13 }}>{p.title}</td>
                      <td style={{ padding:'11px 16px', fontFamily:'JetBrains Mono,monospace', fontSize:12 }}>{Number(p.total_score).toFixed(1)}/{p.total_marks}</td>
                      <td style={{ padding:'11px 16px', minWidth:100 }}>
                        <div style={{ display:'flex', alignItems:'center', gap:6 }}>
                          <div style={{ flex:1, height:4, background:'#f3f4f6', borderRadius:2, overflow:'hidden' }}>
                            <div style={{ height:'100%', width:`${pct}%`, background:`linear-gradient(90deg,${color}88,${color})`, borderRadius:2 }}/>
                          </div>
                          <span style={{ fontSize:10, color, fontFamily:'JetBrains Mono,monospace', fontWeight:700, flexShrink:0 }}>{pct}%</span>
                        </div>
                      </td>
                      <td style={{ padding:'11px 16px' }}>
                        <span style={{ padding:'3px 10px', borderRadius:6, background:`${color}15`, color, fontSize:10, fontWeight:800 }}>{p.grade}</span>
                      </td>
                      <td style={{ padding:'11px 16px', fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>
                        {p.submit_time?new Date(p.submit_time).toLocaleDateString():'-'}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}
